def normalize_tags(tags):
    seen = set()
    result = []
    for tag in tags:
        if not isinstance(tag, str):
            raise TypeError("tags must contain strings")
        key = tag.casefold()
        if key not in seen:
            seen.add(key)
            result.append(tag)
    return result

def most_common_word(words):
    if not words:
        raise ValueError("words must not be empty")

    counts = {}
    most_common = words[0]
    highest_count = 0

    for word in words:
        counts[word] = counts.get(word, 0) + 1
        if counts[word] > highest_count:
            most_common = word
            highest_count = counts[word]

    return most_common

def intersection_labels(first, second):
    result = []
    for label in first:
        if label not in result and label in second:
            result.append(label)
    return result

def common_suffix(words):
    words = list(words)
    if not words:
        return ""
    if any(not isinstance(word, str) for word in words):
        raise TypeError("all words must be strings")

    suffix_length = min(len(word) for word in words)
    for index in range(suffix_length):
        character = words[0][-index - 1]
        if any(word[-index - 1] != character for word in words[1:]):
            break
    else:
        index += 1

    return words[0][len(words[0]) - index:] if suffix_length else ""

def parse_clock(text):
    import re

    if not isinstance(text, str):
        raise TypeError("text must be a string")

    match = re.fullmatch(r"(1[0-2]|[1-9]):([0-5]\d) (AM|PM)", text)
    if match is None:
        raise ValueError("invalid 12-hour clock value")

    hour = int(match.group(1))
    minute = int(match.group(2))
    marker = match.group(3)

    if hour == 12:
        hour = 0
    if marker == "PM":
        hour += 12

    return hour * 60 + minute

def sort_events(events):
    from datetime import datetime

    if events is None or isinstance(events, (str, bytes)) or not hasattr(events, "__iter__"):
        raise TypeError("events must be an iterable of dictionaries")

    parsed_events = []
    timezone_awareness = None

    for event in events:
        if not isinstance(event, dict):
            raise TypeError("each event must be a dictionary")
        if "time" not in event or not isinstance(event["time"], str):
            raise ValueError("each event must contain a string 'time' field")

        time_value = event["time"]
        try:
            parsed_time = datetime.fromisoformat(
                time_value[:-1] + "+00:00" if time_value.endswith(("Z", "z")) else time_value
            )
        except ValueError as exc:
            raise ValueError(f"invalid ISO date-time: {time_value!r}") from exc

        current_awareness = parsed_time.tzinfo is not None
        if timezone_awareness is None:
            timezone_awareness = current_awareness
        elif timezone_awareness != current_awareness:
            raise ValueError("events must use either all timezone-aware or all naive date-times")

        parsed_events.append((parsed_time, event))

    return [event for _, event in sorted(parsed_events, key=lambda item: item[0])]

def matrix_multiply(left, right):
    from collections.abc import Sequence
    from numbers import Number

    def validate(matrix, name):
        if not isinstance(matrix, Sequence) or isinstance(matrix, (str, bytes)):
            raise TypeError(f"{name} must be a sequence of rows")

        if not matrix:
            return 0

        if not all(isinstance(row, Sequence) and not isinstance(row, (str, bytes))
                   for row in matrix):
            raise TypeError(f"{name} must contain row sequences")

        column_count = len(matrix[0])
        if any(len(row) != column_count for row in matrix):
            raise ValueError(f"{name} must be rectangular")

        if any(not isinstance(value, Number) for row in matrix for value in row):
            raise TypeError(f"{name} must contain only numbers")

        return column_count

    left_columns = validate(left, "left")
    right_columns = validate(right, "right")
    right_rows = len(right)

    if left_columns != right_rows:
        if not (not right and left_columns == 0):
            raise ValueError(
                "the number of columns in left must match the number of rows in right"
            )

    if not left:
        return []

    if not right:
        return [[] for _ in left]

    return [
        [
            sum(left_value * right_value
                for left_value, right_value in zip(left_row, right_column))
            for right_column in zip(*right)
        ]
        for left_row in left
    ]

def count_islands(grid):
    try:
        rows = list(grid)
    except TypeError as exc:
        raise TypeError("grid must be an iterable of rows") from exc

    if not rows:
        return 0

    normalized = []
    width = None

    for row in rows:
        try:
            cells = list(row)
        except TypeError as exc:
            raise TypeError("each row must be iterable") from exc

        if width is None:
            width = len(cells)
        elif len(cells) != width:
            raise ValueError("grid must be rectangular")

        for cell in cells:
            if type(cell) is not int or cell not in (0, 1):
                raise ValueError("grid cells must be 0 or 1")

        normalized.append(cells)

    visited = [[False] * width for _ in normalized]
    islands = 0

    for row in range(len(normalized)):
        for col in range(width):
            if normalized[row][col] != 1 or visited[row][col]:
                continue

            islands += 1
            visited[row][col] = True
            stack = [(row, col)]

            while stack:
                current_row, current_col = stack.pop()

                for next_row, next_col in (
                    (current_row - 1, current_col),
                    (current_row + 1, current_col),
                    (current_row, current_col - 1),
                    (current_row, current_col + 1),
                ):
                    if (
                        0 <= next_row < len(normalized)
                        and 0 <= next_col < width
                        and not visited[next_row][next_col]
                        and normalized[next_row][next_col] == 1
                    ):
                        visited[next_row][next_col] = True
                        stack.append((next_row, next_col))

    return islands
